(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["mt"] = {"ui":{"skip":"Aqbeż għall-kontenut","back":"← Lura għal AI-gile","lang.button":"Lingwa: {name}","lang.dialog":"Agħżel lingwa","lang.search":"Fittex lingwa","lang.none":"Ebda lingwa ma taqbel","lang.notYet":"Għad m'hemmx traduzzjoni għal {name}","theme.aria":"Aqleb it-tema: ċara, skura jew sewda","theme.toLight":"Aqleb għat-tema ċara","theme.toDark":"Aqleb għat-tema skura","theme.toBlack":"Aqleb għat-tema sewda (iswed veru, faċli fuq skrins OLED)","words.underline":"Issottolinja dawn il-kliem fil-paġna","words.underlineHelp":"Għaddi l-maws minn fuq kelma b'linja ta' tikek, jew agħfasha, biex tara xi tfisser.","words.col.todo":"Karti magħżula għalissa: it-tim se jibda minn dawn wara.","words.col.doing":"AI qed taħdem fuq din il-karta bħalissa.","words.col.review":"AI waħda lestiet ix-xogħol; oħra tivverifikah qabel ma jaslilek.","words.col.verify":"Qed jistenniek: ippruvah u għid jekk jaħdimx.","words.col.team":"In-noti jew it-tweġibiet tiegħek, qed jistennew li t-tim jerfagħhom.","words.col.done":"Lest u aċċettat.","index.title":"AI-gile: it-tim tal-iżvilupp tiegħek tal-AI, fuq bord wieħed","index.description":"AI-gile huwa bord kanban għal timijiet tal-kodiċi bl-AI. Jaħdmu waqt li torqod; inti tirċievi munzell wieħed qasir ta' affarijiet biex tiddeċiedi, tittestja u taċċetta.","hero.logoAlt":"Ikona tal-bord ta' AI-gile","hero.h1.html":"It-tim tal-iżvilupp tiegħek tal-AI, fuq bord&nbsp;wieħed.","hero.alpha":"🐣 Pre-alpha magħluqa","hero.alphaTitle":"Bikri u mhux lest: grazzi li qed tipprova!","hero.lede":"Jibnu waqt li torqod. Tqum għal munzell wieħed qasir: ftit mistoqsijiet, ftit affarijiet biex tittestja, djamant vjola jew tnejn. Ikklikkja, aċċetta, u lura għall-kafè tiegħek.","dl.windows":"Applikazzjoni għal Windows","dl.browser":"Mexxiha fil-browser tiegħek","dl.messenger":"📱 Messenger għat-telefon tiegħek","dl.soon":"Dalwaqt","dl.notify":"🔔 Għarrafni meta tiftaħ","dl.notifySmall":"Alpha jew beta","hero.secondary":"Agile, imma t-tim qatt ma jeħtieġ kafè għall-istand-up. (Jagħmlu l-istand-ups xorta waħda.)","pitch.h2":"AI-gile fi kliem kemm trid","pitch.lede":"Agħżel tul, minn kelma waħda sa 144. Kull tul huwa deskrizzjoni waħedha, miktuba għal dak id-daqs. Iġbed is-slider jew uża t-tasti tal-vleġeġ.","pitch.rangeLabel":"Tul f'kliem","pitch.dice":"🎲 verżjoni oħra","pitch.words.one":"{n} kelma","pitch.words.other":"{n} kelma","pitch.letters.one":"{n} ittra","pitch.letters.other":"{n} ittra","pitch.chars.one":"{n} karattru","pitch.chars.other":"{n} karattru","count.line.html.one":"{n} karta fuq il-bord bħalissa","count.line.html.other":"{n} karta fuq il-bord bħalissa","people.humans.html.one":"👥 {n} bniedem","people.humans.html.other":"👥 {n} bniedem","people.agents.html.one":"🤖 {n} aġent","people.agents.html.other":"🤖 {n} aġent","people.working.html.one":"⚡ {n} qed jaħdem bħalissa","people.working.html.other":"⚡ {n} qed jaħdmu bħalissa","pre.title":"AI-gile: qed tinbena xi ħaġa","pre.description":"Hawn qed tinbena xi ħaġa: bord fejn timijiet tal-AI jibnu dak li titlob, u jgħallmuk waqt li jaħdmu. Għalissa pre-alpha magħluqa mal-ħbieb.","pre.h1":"Hawn qed tinbena xi ħaġa. 🤫","pre.line":"Bord fejn timijiet tal-AI jibnu dak li titlob, u jgħallmuk waqt li jaħdmu. Għalissa pre-alpha magħluqa mal-ħbieb.","pre.btn":"🔔 Għarrafni meta tiftaħ","pre.peek":"Wara l-ħġieġ: il-bord veru, live. Kull karta hija strixxa kkulurita.","pre.peekFake":"Wara l-ħġieġ: hekk jidher bord fuq ix-xogħol.","pre.night":"🌙 Il-għassa tal-lejl qed imexxi · 😴 il-bniedem qed jistrieħ","features.aria":"X'jagħmel","f.pile.h":"Munzell wieħed għalik","f.pile.html":"<b>Għalik</b> iżomm kollox li qed jistenniek, fil-proġetti kollha: mistoqsijiet, affarijiet biex tittestja, kompiti li bniedem biss jista' jagħmel. Il-kju tiegħek jgħid x'inhu li jmiss u kemm se jieħu.","f.sleep.h":"Timijiet li jaħdmu waqt li torqod","f.sleep.p":"Kull proġett għandu lead u tim ta' aġenti tal-AI. Ikkumenta fuq karta u t-tim iqum, jagħmel ix-xogħol, u jirritornaha lura b'passi li bniedem għajjien jista' jsegwi.","f.tester.h":"Tester tal-AI jiċċekkja l-ewwel","f.tester.p":"Qabel ma xi ħaġa tasal għandek, tester isegwi l-passi f'kopja tal-app u juri x'ra, b'screenshot. Għaddi minn dawk li għaddew u aċċetta b'klikk wieħed.","f.proof.h":"Provi, mhux wegħdiet","f.proof.p":"Kull konsenja turi x'inbidel: il-fajls, id-diff, l-iscreenshots. M'għandekx bżonn tiftaħ kull app biex tara jekk huwiex lest.","f.chat.h":"Iddiskuti mal-leads tiegħek","f.chat.p":"Strixxa bi stil ta' Discord: ikona waħda għal kull proġett, djamanti vjola għal dak li jeħtieġek. Ibgħat idea lil lead; jagħmilha karti u pjan, b'buttuna ✅ Go.","f.tidy.h":"Iżomm lilu nnifsu f'ordni","f.tidy.p":"Karti relatati jingħaqdu f'waħda, titli mħawdin jissewwew, u kontroll tat-tokens iżomm il-kodiċi irqiq. Inqas affarijiet biex taqleb bejniethom, inqas biex taħseb fihom.","f.private.h":"Tiegħek, fuq il-kompjuter tiegħek","f.private.li1":"Il-bord jaħdem fuq il-magna tiegħek stess u jwieġeb lilek biss.","f.private.li2":"Il-messaġġi privati bejn in-nies huma ċifrati end-to-end.","f.private.li3":"L-ebda kont, l-ebda trackers, l-ebda cookies.","f.lang.h":"Bil-lingwa tiegħek","f.lang.p":"Aktar minn 120 lingwa, mill-Malti, il-Welsh u l-Ġappuniż sal-pirata, Yoda u l-Klingon, b'qlib mgħaġġel lura għall-Ingliż għat-termini tekniċi.","f.service.h":"Minn idea għal servizz veru","f.service.p":"Bnejt xi ħaġa bl-AI li issa n-nies qed jużawha? Immarkaha bħala servizz u l-bord jgħinek tmexxiha sew: uptime checks, paġna tal-istatus pubblika, inċidenti b'rapport, bidliet li jeħtieġu Go, backups iċċekkjati kuljum. L-Għajnuna tgħallmek kull pass hekk kif timxi.","msgr.h2":"AI-gile Messenger: it-tim tiegħek fil-but","msgr.p1":"Kellem lit-tim tal-AI tiegħek mingħajr ma tiftaħ il-bord. Iċċettja mal-mexxejja tal-proġetti u mal-ħbieb tiegħek, ara l-passi tat-test ta' karta u wieġeb għalihom, kollox mit-telefon tiegħek.","msgr.p2":"Biex tqabbdu, skennja kodiċi QR fuq il-bord tiegħek. L-ewwel darba? Chat demo ħbiberija turik kollox.","msgr.when":"L-ewwel Android, imbagħad verżjoni web għat-telefowns u għall-iPhone.","msgr.who":"Il-mexxej tal-proġett tiegħek","msgr.b1":"It-tiswija tal-modalità skura lesta. Trid il-passi tat-test?","msgr.b2":"Iva, jekk jogħġbok!","msgr.b3":"1. Iftaħ l-Issettjar. 2. Agħżel Skur. Jidher sew?","tl.aria":"Skeda taż-żmien mill-ewwel konversazzjoni sal-pjan","tl.h2":"Mill-ewwel chat sa dak li jmiss","tl.lede":"Dati u ħinijiet reali, fiż-żona tal-ħin tiegħek. Wara llum huwa l-pjan, mingħajr dati mwiegħda.","tl.today":"Illum","tl.planned":"ippjanat","tl.doing":"għaddej","tl.cards.one":"{n} karta","tl.cards.other":"{n} karta","join.h2":"Ingħaqad magħna","join.lede":"AI-gile qed jinbena minn wieħed stramb b'daqna, b'AuDHD u xi battalji mas-saħħa mentali, u numru kbir ta' aġenti paċenzjużi. Għalissa huwa privat, alpha magħluqa ma' ħbieb. Trid tipprova meta jinfetaħ?","join.btn":"Irreġistra l-interess","join.small":"Se nibagħtulek email, xejn aktar","footer.tag":"AI-gile. L-ebda trackers, l-ebda cookies, l-ebda kafè għall-istand-up.","footer.licence":"Liċenzja tan-negozju","footer.status":"Status","footer.privacy":"X'inżommu","footer.thanks":"Sejħiet grazzi għal ChilledChat","form.sending":"Qed jintbagħat…","form.failed":"Dak ma ħadimx: erġa' pprova aktar tard.","form.offline":"Ma setgħetx tintlaħaq AI-gile: erġa' pprova aktar tard.","form.keep":"Nużaw dan biss biex inwieġbuk, imbagħad inħassruh. L-ebda trackers, l-ebda cookies.","form.keepLink":"X'inżommu","interest.title":"AI-gile: għarrafni meta tiftaħ l-alpha","interest.description":"Ħalli l-email tiegħek biex tisma' meta tinfetaħ l-alpha jew il-beta magħluqa ta' AI-gile.","interest.h1":"🔔 Għarrafni meta tiftaħ","interest.lede":"AI-gile qiegħed f'pre-alpha magħluqa. Ħalli l-email tiegħek u niktbulek darba, meta jkun hemm post għalik.","interest.email":"L-email tiegħek","interest.which":"Liema test?","interest.alpha":"Alpha magħluqa: bikrija, mhux rfinuta, ħafna bidliet","interest.beta":"Beta: aktar stabbli, aktar tard","interest.both":"Kwalunkwe, dik li tiġi l-ewwel","interest.submit":"Poġġini fuq il-lista","interest.thanks":"Grazzi! Int fuq il-lista.","licence.title":"AI-gile: liċenzja tan-negozju","licence.description":"Qed tuża AI-gile fin-negozju tiegħek? Applika għal liċenzja tan-negozju b'xejn.","licence.h1":"📜 Liċenzja tan-negozju","licence.lede":"Qed tuża AI-gile x-xogħol? Għidilna min int u x'tagħmel. Jekk jagħmel xi ġid, il-liċenzja hija b'xejn.","licence.company":"Kumpanija","licence.website":"Websajt","licence.what":"X'tagħmel","licence.how":"Kif jgħin id-dinja","licence.email":"Email","licence.submit":"Applika","licence.thanks":"Grazzi! Nirrispondulek bl-email.","status.title":"Status ta' AI-gile","status.h1":"Status ta' AI-gile","status.quiet":"Kollox kwiet","status.intro":"AI-gile qed jaħdem bħalissa? Din il-paġna tiċċekkja s-sit, il-qsim tal-bordijiet, is-sejħiet u t-tniżżil kull 5 minuti.","status.up":"Qed jaħdem (wieġeb f'{ms} ms)","status.slow":"Ma weġibx għall-aħħar ċekk, qed nerġgħu nippruvaw","status.down":"Waqaf: ma weġibx għall-aħħar żewġ ċekkijiet","status.svc.web":"Sit web","status.svc.web.offers":"Dan is-sit: x'inhu AI-gile, u l-formola tal-interess","status.svc.boards":"Qsim tal-bordijiet","status.svc.boards.offers":"Bordijiet pubbliċi, messaġġi bejn il-ħbieb u stediniet","status.svc.calls":"Sejħiet","status.svc.calls.offers":"Vuċi, vidjo u qsim tal-iskrin f'AI-gile","status.svc.download":"Tniżżil","status.svc.download.offers":"L-installatur għal Windows u l-links tal-istediniet","status.checking":"Qed jiċċekkja…","status.offline":"Is-servizz tal-istatus ma jistax jintlaħaq bħalissa (qed nerġgħu nippruvaw)","status.updated":"aġġornat {ago}","status.justNow":"għadu kif","status.min":"{n} min ilu","status.hours":"{n} sieg ilu","status.days":"{n} j ilu","privacy.title":"AI-gile: x'inżommu","privacy.h1":"X'inżommu","privacy.lede":"Fil-qosor: biss dak li tibgħatilna, u mhux għal żmien twil.","privacy.only":"Biss dak li tibgħatilna: dak li tikteb f'formola, bħall-email tiegħek. Xejn iktar dwarek.","privacy.sealed":"Jiġi ssiġillat biex is-server tagħna ma jkunx jista' jaqrah: fil-browser tiegħek qabel ma jitlaq (fuq browser eqdem, hekk kif jasal). Il-bord tagħna biss jista' jiftħu.","privacy.server":"Jitħassar mis-server hekk kif jasal fuq il-bord tagħna. Kull ma jibqa' hemm wara 30 jum jitħassar xorta waħda.","privacy.board":"Inżommuh fuq il-bord tagħna biss sakemm inwieġbuk, imbagħad inħassruh minn hemm ukoll.","privacy.none":"L-ebda trackers, l-ebda cookies, l-ebda analitika.","privacy.local":"Il-lingwa tiegħek u l-għażla bejn tema ċara jew skura jibqgħu fil-browser tiegħek. Qatt ma jintbagħtulna.","privacy.ask":"Trid li jitħassar qabel? Wieġeb l-email tagħna u għidilna.","live.h2":"Ara kif qed jinbena, live","live.caption":"Kull karta hija moħbija: tara l-forma tax-xogħol, mhux il-kliem.","live.watching.one":"live: {n} qed josservaw","live.watching.other":"live: {n} qed josservaw","live.last.now":"L-aħħar karta tmexxiet ftit ilu","live.last.min.one":"L-aħħar karta tmexxiet {n} minuta ilu","live.last.min.other":"L-aħħar karta tmexxiet {n} minuti ilu","live.last.hour.one":"L-aħħar karta tmexxiet {n} siegħa ilu","live.last.hour.other":"L-aħħar karta tmexxiet {n} sigħat ilu","live.last.day.one":"L-aħħar karta tmexxiet {n} jum ilu","live.last.day.other":"L-aħħar karta tmexxiet {n} jiem ilu","live.offline":"Il-bord live qed jieħu nifs. Erġa' ejja dalwaqt.","live.cols":"Backlog|Biex isir|Għaddej|It-tim qed jivverifika|Għalik biex tittestja|Għat-tim|Lest","pitch.words.few":"{n} kelmiet","pitch.words.many":"{n} kelma","pitch.letters.few":"{n} ittri","pitch.letters.many":"{n} ittra","pitch.chars.few":"{n} karattri","pitch.chars.many":"{n} karattru","count.line.html.few":"{n} karti fuq il-bord bħalissa","count.line.html.many":"{n} karta fuq il-bord bħalissa","tl.cards.few":"{n} karti","tl.cards.many":"{n} karta"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Iddelegat."]},{"n":2,"texts":["Robots jaħdmu.","Aġenti, f'ordni.","Ideat, mibnija."]},{"n":3,"texts":["Kanban għar-robots.","Ideat isiru funzjonijiet.","B'xejn, lokali, ittestjat."]},{"n":5,"texts":["Bord kanban fejn jibnu l-aġenti.","Inti tikteb karti. Aġenti jibnu.","B'xejn, lokali, ittestjat, ftit iblah."]},{"n":8,"texts":["Bord kanban b'xejn fejn jaħdmu l-aġenti tal-AI.","Ikteb idea waħda. L-aġenti jibnuha. Inti taċċettaha.","Agile għal bniedem wieħed u ħafna robots paċenzjużi."]},{"n":13,"texts":["Bord kanban fuq il-kompjuter tiegħek fejn l-aġenti tal-AI jieħdu l-karti.","Ikteb idea. Tim sħiħ ta' aġenti jibnuha. Wara tester jiċċekkjaha sew għalik.","B'xejn, mingħajr kontijiet jew trackers: bord, ftit robots, u inti fil-kontroll."]},{"n":21,"texts":["AI-gile huwa bord kanban biex taħdem ma' aġenti tal-kodiċi bl-AI. Huma jieħdu l-karti kollha; inti tittestjahom u taċċettahom.","Kull proġett għandu lead u tim ta' aġenti tal-AI. Ikkumenta fuq kwalunkwe karta u t-tim jibda jaħdem.","Bord personali tal-affarijiet li jridu jsiru, b'xejn, li jaħdem fuq il-kompjuter tiegħek. Dawk li jaħdmu huma robots. Dak li jgħid iva int."]},{"n":34,"texts":["Inti tpoġġi l-ideat tiegħek fuq bord. Tim ta' aġenti tal-AI jibdilhom f'funzjonijiet li jaħdmu, jittestjahom, u jirritornawhom b'passi biex tipprova. Xejn ma jgħodd bħala lest sakemm int ma tgħidx hekk.","AI-gile huwa bord kanban magħmul id-dar li Rich bena b'ħafna għajnuna mill-aġenti li issa jmexxi. Huwa b'xejn, jaħdem fuq il-kompjuter tiegħek, u jinqasam ma' ħbieb, mhux jinbigħ.","Immaġina bord kanban tas-soltu, b'kolonni minn Backlog sa Lest, ħlief li l-karti jittieħdu mill-aġenti tal-AI. Jirrappurtaw il-progress, jistaqsu meta jibqgħu mwaħħla, u dejjem jistennew l-approvazzjoni tiegħek qabel ma jmorru 'l quddiem."]},{"n":55,"texts":["AI-gile huwa bord kanban fejn it-tim huwa magħmul minn aġenti tal-AI. Kull proġett għandu lead li jippjana x-xogħol u ħaddiema li jibnuh. Meta funzjoni tkun lesta, tester tal-AI jipprovaha u jieħu screenshot, imbagħad tasal fuq il-munzell tiegħek. Aċċettaha, jew ikkumenta u jerġgħu jaħdmu fuqha.","Beda bħala mod ta' persuna waħda biex iżomm rendikont ta' ħafna sessjonijiet tal-kodiċi bl-AI f'daqqa, u kiber f'bord veru. Jaħdem fuq il-magna tiegħek, ma jeħtieġ l-ebda kont u m'għandu l-ebda trackers. Huwa b'xejn għall-ħbieb u għal min hu kurjuż. Għadu wkoll mhux lest, għalhekk stenna xi truf mhux irfinati u sorpriża minn żmien għal żmien.","Din hija l-verżjoni onesta tal-istorja kollha. Xorta trid ikollok l-ideat, u xorta trid tiċċekkja r-riżultati. Dak li jagħmel AI-gile huwa dak kollu li hemm bejniethom: iżomm il-karti f'ordni, iqajjem l-aġent t-tajjeb meta tikkumenta, juri eżattament x'inbidel, u jżomm kollox f'munzell qasir wieħed biss għalik, mingħajr storbju."]},{"n":89,"texts":["AI-gile huwa bord kanban kompletament b'xejn li tmexxi fuq il-kompjuter tiegħek stess. Minflok in-nies, kull proġett għandu tim sħiħ ta' aġenti tal-AI: lead li jibdel l-ideat tiegħek f'karti u pjan, u għajnuna li tieħu l-karti skont il-prijorità. Meta xi ħaġa tinbena, tester tal-AI isegwi l-passi tat-test u juri lilek x'ra, b'screenshot. Imbagħad tistenna f'munzell wieħed biss jismu Għalik. Inti taċċettaha, jew tikkumenta u t-tim jerġa' jipprova mill-ġdid. Xejn ma jasal qatt f'Lest mingħajrek.","Ftit karatteristiċi li forsi ma tistennihomx. Għassa tal-lejl iżżomm il-kolonna Biex isir mimlija waqt li torqod, billi tagħżel karti li ma jeħtieġux tweġiba minnek. Għadd tat-tokens juri kemm użaw l-aġenti llum u din il-ġimgħa, u l-Mod bla Tokens jgħidilhom jieqfu jonfqu. Tista' tibgħat messaġġi lill-ħbieb, u l-messaġġi privati huma ċifrati end-to-end. Il-bord jitkellem madwar 120 lingwa, fosthom il-Malti, il-pirata u l-Klingon. Xejn minn dan ma jiswa xejn, u ħadd ma qed jipprova jbigħhulek.","AI-gile huwa proġett żgħir u personali, mhux kumpanija. Rich xtaq jieħu ħsieb diversi proġetti tal-kodiċi bl-AI mingħajr ma jiftaħ kull app biex jiċċekkjahom, allura hu u l-aġenti bnew bord għal dan, u mbagħad użaw il-bord biex jibnu l-bqija tiegħu nnifsu. Qiegħed f'pre-alpha magħluqa, li jfisser li jaħdem, il-biċċa l-kbira, għal ftit ħbieb. M'hemm l-ebda paġna tal-prezzijiet, l-ebda newsletter u l-ebda pjan ta' tkabbir. Jekk jidher utli, tista' titlob biex tipprovah meta jinfetaħ ftit aktar."]},{"n":144,"texts":["AI-gile huwa bord kanban għal bniedem wieħed u ħafna aġenti tal-AI paċenzjużi. Jaħdem fuq il-kompjuter tiegħek stess u huwa għal kollox b'xejn. Inti żżid proġetti, u kull proġett jaqla' lead u tim żgħir. Tiddiskuti mal-lead, kemmxejn bħal fuq Discord, u tiddeskrivi idea; il-lead jagħmilha karti u pjan, u jistenna li tagħfas Go. It-tim jaħdem mal-karti skont il-prijorità, b'għodda sempliċi tal-linja tal-kmandi magħmula għall-mudelli tal-lingwa. Qabel ma xi ħaġa tirritorna għandek, tester tal-AI isegwi l-passi f'kopja tal-app u jwaħħal screenshot. Ix-xogħol lest jasal fuq il-munzell tiegħek, mal-fajls li nbidlu, id-diff u l-iscreenshots. Inti taċċettah, jew tħalli kumment u t-tim iqum u jerġa' jipprova. Kull ma jsir jidher fuq il-bord, f'kolonni mill-Backlog sa Lest. Ma jeħtieġ l-ebda kont. Int biss tista' tmexxi karta għal Lest.","Jum ma' AI-gile, bejn wieħed u ieħor. Filgħaxija tħalli ftit kummenti: din il-buttuna hi fil-post ħażin, dik il-lista għandha tinżamm ordnata, nistgħu nkollhom mod skur. Tmur torqod. L-aġenti jaqraw il-kummenti, jagħmlu l-bidliet, jittestjawhom u jirritornawhom lilek. Jekk Biex isir jispiċċa, l-għassa tal-lejl timlieh mill-backlog b'karti li ma jeħtieġu l-ebda tweġiba minnek. Filgħodu hemm munzell qasir wieħed: par ta' mistoqsijiet u ftit affarijiet biex tipprova, kull wieħed b'passi li persuna ngħasana tista' ssegwi u screenshot ta' kif jaħdem. Tikklikkja minnu, taċċetta t-tajba u tibgħat lura l-bqija. Għadd tat-tokens juri kemm intuża dan kollu, u l-Mod bla Tokens hemm għal ġimgħat irqaq. Jekk xi ħaġa ma tkunx ċara, it-tim jistaqsi qabel ma jmur 'il quddiem. Imbagħad tieħu l-kolazzjon, li l-aġenti għadhom ma jistgħux jgħinu fih.","L-ewwel, x'mhuwiex AI-gile. Mhuwiex startup, mhuwiex għall-bejgħ, u ħadd ma qed jiġbor id-dejta tiegħek. Huwa bord b'xejn li jaħdem fuq il-kompjuter tiegħek, mingħajr kontijiet, trackers jew cookies. X'inhu: post wieħed irranġat biex tara l-proġetti kollha tiegħek tal-kodiċi bl-AI f'daqqa, b'tim ta' aġenti jagħmlu l-karti u inti tieħu d-deċiżjonijiet. Jingħaqad karti relatati, isewwi titli mħawdin, u josserva kemm il-kodiċi jibqa' irqiq. Jitkellem madwar 120 lingwa, mill-Malti sal-pirata u l-Klingon. Il-ħbieb jistgħu jibagħtu messaġġi lil xulxin, privatament u ċifrati. Inbena minn Rich u numru kbir ta' aġenti paċenzjużi, li l-aktar użawh huma stess. Ma jbigħ xejn, ma jitlob xejn, u ma jgħaddi xejn lil ħadd. Qiegħed f'pre-alpha magħluqa, għalhekk f'xi postijiet għadu mhux rfinut. Jekk jidher divertenti, itlob b'ġentilezza u forsi tidħol kmieni."]}],"quips":{"1":"Kelma waħda. Kuraġġuża. Forsi kuraġġuża żżejjed.","3":"Tliet kelmiet. Diġà aktar onesti mill-biċċa l-kbira tal-paġni tal-prodotti.","8":"Tmien kelmiet. Għadu iqsar minn stand-up.","21":"It-tulijiet huma story points, mill-mod. Naturalment.","55":"Ħamsa u ħamsin kelma. Żewġ karti ntemmu waqt li qrajt dan.","144":"Din kienet it-tawwala. M'hemm l-ebda 233. L-aġenti marru jorqdu."}},"timeline":{"first-idea.name":"L-ewwel idea","first-idea.line":"L-ewwel konversazzjoni ta' kollox, qabel ma kien jeżisti kodiċi.","first-board.name":"L-ewwel bord","first-board.line":"Bord li jżomm rendikont tal-bini tiegħu stess: karti, kolonni, ġbid u ċaqliq, proġetti.","team-roles.name":"Tim u rwoli","team-roles.line":"Profili tal-aġenti, mudelli tat-timijiet, spazji u min jagħmel xiex.","install.name":"Installazzjoni u rilaxxi","install.line":"Zip li ħabib jista' jinstalla, aġġornamenti awtomatiċi, kanali u rollback.","usage-saver.name":"Tfaddil tal-użu","usage-saver.line":"Kejl ta' kemm jiswew it-tħaddim, kodiċi irqiq, u l-limitu tiegħek jitfaddal.","friends.name":"Ħbieb u qsim","friends.line":"DMs privati, relay imħawwad, stediniet, rwoli u proġetti maqsuma.","languages.name":"Lingwi","languages.line":"Kull test tal-iskrin f'fajl tal-lingwa, bl-Olandiż u l-Fjamming l-ewwel.","ai-tester.name":"Tester tal-AI","ai-tester.line":"Tester jiċċekkja kull konsenja l-ewwel u juri x'ra.","website.name":"Is-sit","website.line":"aigile.lol, it-teaser u din l-iskeda taż-żmien.","streaming.name":"Chat u streaming","streaming.line":"Discord, Twitch, OBS, mod tal-istreamer, GIFs u emojis.","no-ai.name":"Edizzjoni bla AI","no-ai.line":"Bord għal nies li jikkodifikaw mingħajr AI, u bordijiet pubbliċi.","night-watch.name":"Għassa tal-lejl","night-watch.line":"Għassies u Scrum Master iżommu t-timijiet fuq il-binarju waqt li torqod.","p-more.name":"Kull ħaġa oħra","p-more.line":"Ideat iżgħar li għadhom jistennew id-dawra tagħhom.","p-android.name":"Telefon u Android","p-android.line":"Dħul fil-bord tiegħek mit-telefon, imbagħad app nattiva għall-Android.","p-release.name":"Alpha u aktar 'il quddiem","p-release.line":"Alpha magħluqa, is-sit live, imbagħad il-beta.","p-languages.name":"Aktar lingwi","p-languages.line":"130 lingwa, u mod ta' immersjoni għal min qed jitgħallem.","p-engines.name":"Aktar magni tal-AI","p-engines.line":"Agħżel Claude, Codex, Gemini, Copilot jew Cursor għal kull aġent.","p-pro.name":"Prattika professjonali","p-pro.line":"Tikketti tar-riskju, bibien tal-merge, karti tal-inċidenti u ħitan tal-ħarsien.","p-self.name":"Ngħożżuk","p-self.line":"Mod għajjien, tfakkiriet ta' kura personali u 4:20.","p-servers.name":"Servers u skala","p-servers.line":"Settings globali tas-server, rwoli u ppjanar għat-tkabbir.","p-livestream.name":"Żidiet għall-istreaming","p-livestream.line":"Chat ta' Twitch, emojis personalizzati u veduta live pubblika."},"words":{"button":"📖 Termini tekniċi","h":"📖 Kliem spjegat","intro":"Il-kliem li ssib f'AI-gile, b'lingwa sempliċi: kif tibnih, kif tibdlu bla periklu, kif iżżommu jaħdem għan-nies li jużawh, u kif taħdem bħala tim mal-AI.","search":"Fittex kelma…","none":"Ebda kelma ma taqbel ma' dak.","close":"Agħlaq","count":{"one":"{count} kelma","other":"Kliem: {count}"},"groups":[{"id":"build","name":"🛠️ Il-bini"},{"id":"change","name":"🔀 Bidla bla periklu"},{"id":"run","name":"🛎️ It-tmexxija ta' servizz"},{"id":"team","name":"🤝 Ix-xogħol bħala tim (u mal-AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Il-folder tal-kodiċi tal-proġett u l-istorja sħiħa tiegħu ta' commits, ġeneralment miżmum ukoll fuq GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Linja separata ta' xogħol fil-kodiċi, biex isiru bidliet mingħajr ma tmiss il-verżjoni prinċipali.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Snapshot issejvjat tal-kodiċi, b'nota qasira ta' x'inbidel. Dejjem tista' terġa' lura għal wieħed.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Tibgħat snapshots issejvjati (commits) minn dan il-kompjuter fuq GitHub, biex ikunu ssejvjati u kondiviżi."},{"id":"merge","g":"build","word":"Merge","text":"Ngħaqqdu l-bidliet ta' branch lura mal-verżjoni prinċipali."},{"id":"pr","g":"build","word":"Pull request","text":"Titlob li l-bidliet ta' branch jiġu ċċekkjati u mgħaqqda mal-verżjoni prinċipali.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Tirranġa l-kodiċi mingħajr ma tibdel dak li jagħmel: fajls iżgħar, ismijiet iktar ċari, inqas ripetizzjoni."},{"id":"bug","g":"build","word":"Bug","text":"Xi ħaġa li ma taħdimx kif suppost.","also":["bugs"]},{"id":"test","g":"build","word":"Test","text":"Tipprova biċċa xogħol lesta biex tara li tagħmel dak li ntalab, qabel ma taċċettaha.","also":["testijiet","tittestja","jiġu ttestjati"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Qosra għal quality assurance (assigurazzjoni tal-kwalità): il-kontrolli awtomatiċi li jsiru qabel ma xi ħaġa tmur live. Meta l-QA tkun ħamra, xi ħaġa falliet, u ma tistax tmur live sakemm tissewwa.","also":["kontrolli tal-kwalità"]},{"id":"deploy","g":"change","word":"Deploy","text":"Tqiegħed verżjoni ġdida live, pereżempju fuq server fejn in-nies jużawha."},{"id":"release","g":"change","word":"Release","text":"Pakkett b'isem ta' xogħol lest li jmur live flimkien, b'noti qosra fuq x'inbidel. 🚀 Releases jikteb in-noti mill-kards lesti.","also":["releases","rilaxx"]},{"id":"rollback","g":"change","word":"Rollback","text":"Tmur lura għall-aħħar verżjoni li kienet taħdem meta waħda ġdida toħloq problemi. F'AI-gile dan jagħmel checklist tal-passi biex tirreġġa' lura miktuba fuq kull bidla.","also":["roll back","erġa' lura","mreġġa' lura"]},{"id":"live","g":"change","word":"Live","text":"Il-verżjoni vera li n-nies jużaw, mhux kopja biex tipprova l-affarijiet. L-iżviluppaturi jsejħulha wkoll production.","also":["production","produzzjoni"],"noTip":1},{"id":"change","g":"change","word":"Bidla","text":"Bidla ppjanata f'xi ħaġa li n-nies jiddependu fuqha, miktuba minn qabel: x'inhi, għaliex, ir-riskju, meta, u kif tiġi mreġġa' lura. Ibda waħda b'🔀 Ressaq bidla.","also":["bidliet","talba għal bidla","talbiet għal bidla"],"noTip":1},{"id":"risk","g":"change","word":"Riskju","text":"Xi ħaġa li tista' tmur ħażin, b'punteġġ skont kemm hi probabbli u kemm tkun ħażina. ⚠️ Riskji jżommhom f'lista waħda, l-ogħla punteġġ l-ewwel, kull wieħed b'data biex terġa' tħares lejh.","also":["riskji","reġistru tar-riskji"]},{"id":"chgwin","g":"change","word":"Tieqa tal-bidliet","text":"Il-ħinijiet meta l-bidliet jistgħu jmorru live, bħal filgħaxija kwieta ta' nhar ta' Tlieta. Barra minn tieqa, kard tal-bidla ma tistax titlesta, sakemm ma tkunx emerġenza.","also":["twieqi tal-bidliet","tieqa"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Votazzjoni malajr eżatt qabel ma bidla tmur live: kull persuna li trid tapprova tgħid Go jew No go. Tmur 'il quddiem biss meta jaqblu.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approvazzjoni","text":"Tistenna \"iva\" qabel ma jibda x-xogħol. Kard li jressaq xi ħabib, jew bidla, tistenna f'✅ Approvazzjonijiet sakemm tapprovaha jew tirrifjutaha.","also":["approvazzjonijiet"]},{"id":"quiettime","g":"change","word":"Ħin kwiet","text":"Perjodu, bħal stream, demo jew il-lejl, meta xejn ma jmur live. It-timijiet ikomplu jaħdmu u jittestjaw, imma l-mixja live tistenna sakemm jispiċċa. F'postijiet oħra jissejjaħ change freeze.","also":["ħinijiet kwieti","change freeze"]},{"id":"service","g":"run","word":"Servizz","text":"Xi ħaġa li bnejt u li n-nies jiddependu fuqha, bħal websajt jew app, li tiġi mħarsa biex tibqa' taħdem. Immarka “Dan il-proġett huwa servizz” u għid x'joffri, min jużah u min hu on-call.","also":["servizzi","is-servizz"]},{"id":"uptime","g":"run","word":"Uptime check","text":"Kontroll awtomatiku, kull ftit minuti, li s-servizz tiegħek għadu jwieġeb. Jekk jonqos diversi drabi wara xulxin, AI-gile jiftaħ kard ta' inċident waħdu.","also":["uptime","uptime checks","kontroll tal-uptime"]},{"id":"statuspage","g":"run","word":"Paġna tal-istatus","text":"Paġna pubblika li turi jekk servizz hux jaħdem (aħdar, oranġjo jew aħmar) bl-aħħar aġġornament, biex in-nies li jużawh ikunu jistgħu jiċċekkjaw minflok jistaqsu.","also":["paġni tal-istatus","status page"]},{"id":"desk","g":"run","word":"Service desk","text":"Fejn jidħlu l-mistoqsijiet u r-rapporti min-nies li jużaw is-servizz tiegħek. AI-gile jqassam kull wieħed bħala talba, inċident jew idea, u jgħidlek meta jidher qisu xi ħaġa li diġà ġiet irrappurtata.","also":["service desks","help desk","helpdesk","desk tas-servizz"]},{"id":"svcrequest","g":"run","word":"Talba għal servizz","text":"Xi ħadd jitlob xi ħaġa ordinarja, bħal kont ġdid jew ftit għajnuna, minflok jirrapporta li xi ħaġa nkisret. Tistenna d-dawra tagħha; l-inċident jgħaddi l-ewwel.","also":["talbiet għal servizz"]},{"id":"incident","g":"run","word":"Inċident","text":"Xi ħaġa li hija miksura għan-nies li qed jużawha bħalissa, bħall-websajt mitfija. Kard ta' 🔥 inċident taqbeż il-kju: li terġa' taħdem tiġi l-ewwel.","also":["inċidenti","l-inċident"]},{"id":"major","g":"run","word":"Inċident maġġuri","text":"Inċident kbir: ħafna nies affettwati, jew flus jew data f'riskju. Buttuna waħda tpoġġi kull tim fuqu (swarm), tqajjem lil min hu on-call u titlob aġġornament tal-istatus kull 30 minuta.","also":["inċidenti maġġuri"]},{"id":"oncall","g":"run","word":"On-call","text":"Tkun dak li jwieġeb meta xi ħaġa tinkiser, anke bil-lejl. Kull servizz għandu membru tat-tim on-call li jitqajjem l-ewwel għall-inċidenti tiegħu.","also":["on call"]},{"id":"replyby","g":"run","word":"Ħin biex titwieġeb","text":"Kemm kard tista' tistenna għall-ewwel tweġiba, pereżempju siegħa għal inċident. Wara dak il-ħin tieħu arloġġ aħmar, biex xejn ma jintesa bil-kwiet. Jissejjaħ ukoll mira ta' rispons.","also":["ħinijiet biex titwieġeb","mira ta' rispons","miri ta' rispons"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Ħarsa qasira lura wara inċident: x'ġara, x'għen u x'għandu jinbidel, mingħajr ma tagħti tort lil ħadd. Inċident ma jistax jingħalaq mingħajrha.","also":["post-mortems","postmortem","reviżjoni wara l-inċident"]},{"id":"problem","g":"run","word":"Problema","text":"Il-kawża moħbija wara inċident wieħed jew aktar. Kard ta' 🧩 problema tiġbor flimkien inċidenti li jibqgħu jerġgħu jiġru, biex il-kawża tinstab u tissewwa għal dejjem.","also":["problemi","il-problema"],"noTip":1},{"id":"rootcause","g":"run","word":"Kawża ewlenija","text":"Ir-raġuni vera għaliex xi ħaġa nkisret, mhux biss dak li rajt imur ħażin. Sewwi l-kawża ewlenija u l-inċident ma jibqax jerġa' jiġri.","also":["kawżi ewlenin","root cause"]},{"id":"workaround","g":"run","word":"Workaround","text":"Mod kif iżżomm l-affarijiet jaħdmu sakemm it-tiswija vera tkun lesta, bħal tirristartja xi ħaġa meta teħel. Jinkiteb fuq il-kard tal-problema biex ħadd ma jkollu jerġa' jaħsibha.","also":["workarounds","soluzzjoni temporanja"]},{"id":"knownerror","g":"run","word":"Żball magħruf","text":"Problema li l-kawża tagħha hija mifhuma u għandha workaround, imma għadha mhix imsewwija. 🧩 Żbalji magħrufa jniżżilhom, biex kulħadd juża l-workaround minflok iħaffer mill-ġdid.","also":["żbalji magħrufa"]},{"id":"runbook","g":"run","word":"Runbook","text":"Struzzjonijiet pass pass biex issewwi tip ta' problema magħrufa, biex issir bl-istess mod, malajr, kull darba. Wara inċident kbir it-tim jista' jipproponi wieħed biex tagħtih l-OK.","also":["runbooks"]},{"id":"ci","g":"run","word":"Oġġett tal-konfigurazzjoni","text":"Ħaġa waħda li s-servizz tiegħek jiddependi minnha, bħal server, dominju, ċertifikat, ċavetta jew fornitur. 🗂️ Oġġetti tal-konfigurazzjoni jelenkahom għal kull servizz, biex tara x'jaffettwa inċident u x'jeħtieġ tiġdid jew backup.","also":["oġġetti tal-konfigurazzjoni"]},{"id":"expiry","g":"run","word":"Data ta' skadenza","text":"AI-gile iżomm għajnejh fuq dati bħal meta jiskadi ċertifikat jew dominju. 30 jum qabel id-data jagħmel kard waħda biex jiġġeddu, ħalli xejn ma jieqaf jaħdem għal għarrieda.","also":["dati ta' skadenza","skadenza","sorveljanza tal-iskadenzi"]},{"id":"backup","g":"run","word":"Backup","text":"Kopja salvata tad-data tiegħek minn qabel, biex terġa' għaliha jekk xi ħaġa tintilef jew issirilha l-ħsara. AI-gile jagħmel backup tal-bordijiet tiegħek kuljum.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Irkupru","text":"Iġġib lura d-data minn backup. Backup verament jgħodd biss meta tkun taf li jista' jiġi rkuprat, għalhekk ta' min tipprovah kultant.","also":["irkupra","irkuprat","restore"]},{"id":"svcreview","g":"run","word":"Reviżjoni tas-servizz","text":"Ħarsa lura lejn xahar wieħed ta' servizz: inċidenti miftuħa u rranġati, kemm malajr in-nies kisbu tweġiba, uptime u tokens użati. Ir-Reviżjoni xahrija turih għal kull servizz.","also":["reviżjonijiet tas-servizz","reviżjoni xahrija","reviżjonijiet xahrin"]},{"id":"accessreview","g":"run","word":"Reviżjoni tal-aċċess","text":"Kull 90 jum tiċċekkja min għadu jista' jidħol: links ta' qsim, ir-rwoli tal-ħbieb u sigrieti miżmuma. Kull wieħed iżżommu jew tneħħih, ħalli aċċess qadim ma jibqax mitluq hemm.","also":["reviżjonijiet tal-aċċess"]},{"id":"improvements","g":"run","word":"Lista tat-titjib","text":"Dak kollu li t-tim iddeċieda li jtejjeb, f'post wieħed: suġġerimenti tar-retro, azzjonijiet tar-reviżjonijiet u soluzzjonijiet għal problemi, kull wieħed bl-istatus tiegħu. Issibha taħt 📈 Titjib.","also":["listi tat-titjib","titjib"]},{"id":"tokencap","g":"run","word":"Limitu ta' token","text":"Limitu kull xahar fuq it-tokens li l-aġenti ta' servizz jistgħu jużaw. Fi 80% tirċievi twissija; f'100% ix-xogħol fl-isfond tagħhom jistenna sax-xahar ta' wara jew sakemm togħla l-limitu.","also":["limiti ta' token"]},{"id":"backlog","g":"team","word":"Backlog","text":"Ideat u xogħol li għadu mhux ippjanat. Xejn hemmhekk ma jitħadem sakemm ma jmurx għal Biex isir."},{"id":"sprint","g":"team","word":"Sprint","text":"Perjodu qasir ta' xogħol (spiss ġimgħa jew tnejn) b'sett ta' karti miftiehem biex jitlestew.","also":["sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"Check-in rapidu: x'għamel kull membru tat-tim, x'se jagħmel wara, u x'qed iwaqqfu.","also":["standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"Bord b'kolonni (Biex isir, Għaddej, Lest) fejn il-karti jimxu mix-xellug lejn il-lemin hekk kif isir ix-xogħol."},{"id":"wip","g":"team","word":"WIP limit","text":"Work in progress: l-aktar karti li kolonna għandha żżomm, biex it-tim itemm l-affarijiet qabel jibda aktar.","also":["WIP"]},{"id":"dod","g":"team","word":"Definizzjoni ta' Magħmul","text":"Il-checklist qasira tat-tim ta' xi jfisser “magħmul”, bħal ittestjat u spjegat, qabel ma kard tingħatalek. It-tewmija tagħha, id-Definizzjoni ta' Lest biex jibda, tgħid meta kard tkun ċara biżżejjed biex tibda.","also":["Definizzjoni ta' Lest biex jibda","Definition of Done","Definition of Ready"]},{"id":"testpile","g":"team","word":"Munzell tat-test","text":"Il-kards lesti li qed jistennewk tipprovahom, waħda wara l-oħra. Aċċetta waħda jew ibgħatha lura b'nota, u titla' dik li jmiss.","also":["munzelli tat-test"]},{"id":"retro","g":"team","word":"Retro","text":"Ħarsa lura lejn kif jaħdem it-tim, biex taqblu fuq ħaġa waħda li tagħmlu aħjar. F'AI-gile retro tissuġġerixxi bidla fil-mod kif jaħdem it-tim, u int tgħid Go jew Mhux issa.","also":["retros","retrospettiva","retrospettivi"]},{"id":"peerreview","g":"team","word":"Peer review","text":"Par għajnejn ieħor: AI oħra tiċċekkja x-xogħol ta' kull kard qabel ma tasal għandek, biex jgħaddu inqas żbalji.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"Kulħadd fuq il-gverta: kull tim iħalli xogħol ieħor biex jgħin fuq proġett urġenti wieħed sakemm jissolva. Proġetti oħra jistennew sadanittant.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Dak li jżomm ix-xogħol għaddej: jinnota kards imwaħħlin, iqanqal lit-timijiet u jfakkrek f'dak li qed jistenna. F'AI-gile l-Lead Scrum Master jagħmel dan f'kull proġett.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Aġent","text":"AI li taħdem waħedha fuq kompitu: taqra l-kodiċi, tagħmel bidliet, tmexxi kontrolli, u tirrapporta lura.","also":["aġenti","agent","agents"]},{"id":"token","g":"team","word":"Token","text":"L-unità li biha jingħadd l-użu tal-AI: bejn wieħed u ieħor ftit ittri ta' test moqrija jew miktuba. Inqas tokens, aktar jibqa' mill-pjan tiegħek.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Kmand żgħir li jaħdem waħdu f'mument stabbilit, eż. meta tibda sessjoni tal-AI, biex it-tim jisma' l-kummenti tiegħek.","also":["hooks"]}]}};
